import { CountRoll, Button } from "march/ui"

// takipçi sayısı: kısa biçim (12,4 B); takip et düğmesi bir artırır
export function FollowerCount() {
  let $n = 12480
  let $on = false
  return <div sx={{ flex: ["row", "center"], gap: 3 }}>
    <span><strong><CountRoll value={$n} format="compact" /></strong> takipçi</span>
    <Button size="sm" variant={$on ? "secondary" : "primary"} on:click={() => { $on = !$on; $n += $on ? 1 : -1 }}>{$on ? "Takip ediliyor" : "Takip et"}</Button>
  </div>
}

import { CountRoll, Button } from "march/ui"

// CountRoll'un özellikleri: value, format (compact / full / kendi Intl ayarın), hideZero, duration, formatter, spoken,
// roll, stagger, class
export function CountRollLab() {
  let $n = 0
  return <div sx={{ flex: "col", gap: 2 }}>
    <CountRoll class="lab-zero" value={$n} hideZero />
    <CountRoll class="lab-own" value={$n} formatter={(n: number) => `${n} beğeni`} spoken={(n: number) => `${n} kişi beğendi`} roll={false} />
    <CountRoll class="lab-slow" value={1234567} format="compact" duration={900} stagger={60} />
    <Button size="sm" on:click={() => $n += 5}>+5</Button>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { CountRollLab } from "./CountRollLab.tsx"

// CountRollLab'in testleri: kaydedince Testler sekmesinde çalışır
test("formatter kendi metnini yazar ve değer değişince güncellenir", async () => {
  const s = renderTest(() => <CountRollLab />)
  expect(s.get(".lab-own")?.textContent).toContain("0 beğeni")
  await s.click("+5")
  await s.flush(2)
  expect(s.get(".lab-own")?.textContent).toContain("5 beğeni")
})

test("hideZero sıfırı göstermez", () => {
  const s = renderTest(() => <CountRollLab />)
  expect(s.get(".lab-zero")?.textContent?.trim()).toBe("")
})
